/**
 * roadmapBoard — 🛸 MISSION CONTROL: the living roadmap, in-world.
 *
 * A billboard on Vibe Island's north-west lawn that renders the loop
 * the whole VibeVerse runs on:
 *
 *   God Orb wish  →  🌠 latest wishes (live from universe_requests)
 *                →  🔜 up next (Notion roadmap via /roadmap.json)
 *                →  ✅ shipped
 *
 * A beam of golden motes falls from the God Orb into the board — the
 * sky literally feeds the roadmap. /roadmap.json is regenerated by
 * Claude's recurring Mission Control sweep; wishes arrive the moment
 * someone whispers to the orb.
 */
import * as THREE from "three";

interface RoadmapItem {
  idea: string;
  status: string;
  area?: string;
}

interface Wish {
  text: string;
  author: string;
}

export interface RoadmapBoard {
  group: THREE.Group;
  update(dt: number, now: number): void;
  /** Show fresh wishes on the 🌠 strip (redraws the canvas). */
  setWishes(wishes: Wish[]): void;
  /** Grow the golden mote-beam from a point (board-local space). */
  attachWishBeam(fromLocal: THREE.Vector3): void;
}

const W = 1024;
const H = 700;

export function buildRoadmapBoard(): RoadmapBoard {
  const group = new THREE.Group();

  let items: RoadmapItem[] | null = null;
  let generated: string | null = null;
  let wishes: Wish[] = [];

  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d")!;
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;

  const draw = () => {
    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, "#101726");
    bg.addColorStop(1, "#0a1020");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = "rgba(122, 240, 255, 0.55)";
    ctx.lineWidth = 6;
    ctx.strokeRect(4, 4, W - 8, H - 8);

    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = "bold 52px 'Sora', system-ui, sans-serif";
    ctx.shadowColor = "#7af0ff";
    ctx.shadowBlur = 26;
    ctx.fillStyle = "#eafcff";
    ctx.fillText("🛸 MISSION CONTROL", W / 2, 54);
    ctx.shadowBlur = 0;
    ctx.font = "23px 'Manrope', sans-serif";
    ctx.fillStyle = "#7af0ff";
    ctx.fillText("wish it at the God Orb → it lands here → it gets built", W / 2, 100);

    if (!items) {
      ctx.font = "28px 'Manrope', sans-serif";
      ctx.fillStyle = "#9fb2c4";
      ctx.fillText("tuning into mission control…", W / 2, H / 2);
      tex.needsUpdate = true;
      return;
    }

    const shipped = items.filter((i) => i.status === "Done").slice(-7).reverse();
    const next = items.filter((i) => i.status === "Not started").slice(0, 7);

    const drawColumn = (
      title: string,
      color: string,
      list: RoadmapItem[],
      x0: number,
      colW: number,
    ) => {
      ctx.textAlign = "left";
      ctx.font = "bold 30px 'Sora', system-ui, sans-serif";
      ctx.fillStyle = color;
      ctx.fillText(title, x0, 150);
      ctx.fillStyle = "rgba(255,255,255,0.12)";
      ctx.fillRect(x0, 170, colW - 40, 3);
      ctx.font = "23px 'Manrope', sans-serif";
      list.forEach((item, i) => {
        const y = 206 + i * 40;
        ctx.fillStyle = color;
        ctx.fillText(title.startsWith("✅") ? "✦" : "·", x0, y);
        ctx.fillStyle = "#dbe7f3";
        let label = item.idea;
        while (ctx.measureText(label).width > colW - 78 && label.length > 4) {
          label = label.slice(0, -2);
        }
        if (label !== item.idea) label += "…";
        ctx.fillText(label, x0 + 26, y);
      });
    };

    drawColumn("✅ SHIPPED", "#5fd068", shipped, 48, W / 2 - 48);
    drawColumn("🔜 UP NEXT", "#ffd166", next, W / 2 + 24, W / 2 - 48);

    // 🌠 The wish strip — fresh from the God Orb.
    const stripY = 500;
    ctx.fillStyle = "rgba(255, 209, 102, 0.10)";
    ctx.fillRect(24, stripY, W - 48, 150);
    ctx.strokeStyle = "rgba(255, 209, 102, 0.4)";
    ctx.lineWidth = 2;
    ctx.strokeRect(24, stripY, W - 48, 150);
    ctx.textAlign = "left";
    ctx.font = "bold 26px 'Sora', system-ui, sans-serif";
    ctx.fillStyle = "#ffd166";
    ctx.fillText("🌠 LATEST WISHES FROM THE GOD ORB", 48, stripY + 32);
    ctx.font = "italic 22px 'Manrope', sans-serif";
    if (wishes.length === 0) {
      ctx.fillStyle = "#c9b48a";
      ctx.fillText("the orb is listening… whisper the next one", 48, stripY + 74);
    } else {
      wishes.slice(0, 2).forEach((w, i) => {
        const y = stripY + 74 + i * 40;
        ctx.fillStyle = "#ffe9b3";
        let line = `“${w.text}”`;
        while (ctx.measureText(line).width > W - 320 && line.length > 6) {
          line = line.slice(0, -2);
        }
        ctx.fillText(line, 48, y);
        ctx.fillStyle = "#c9b48a";
        ctx.fillText(` — ${w.author}`, Math.min(48 + ctx.measureText(line).width + 8, W - 250), y);
      });
    }

    ctx.textAlign = "center";
    ctx.font = "20px 'Manrope', sans-serif";
    ctx.fillStyle = "#8fa3b8";
    ctx.fillText(`updated ${generated ?? "recently"} · steered from Notion · built by Claude ✨`, W / 2, H - 22);
    tex.needsUpdate = true;
  };
  draw();

  // ---- Structure: posts + panel + night up-light --------------------
  const postMat = new THREE.MeshStandardMaterial({ color: "#4a5462", roughness: 0.7, metalness: 0.3 });
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.18, 4.6, 10), postMat);
    post.position.set(side * 4.4, 2.3, 0);
    group.add(post);
  }
  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(9.2, 6.3),
    new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide }),
  );
  panel.position.y = 3.6;
  group.add(panel);
  const glow = new THREE.PointLight(0x7af0ff, 5, 14, 1.8);
  glow.position.set(0, 1.2, 1.6);
  group.add(glow);

  // ---- Wish beam: golden motes falling from the God Orb -------------
  const BEAM_TARGET = new THREE.Vector3(0, 6.4, 0); // just above the panel
  let motes: THREE.Sprite[] | null = null;
  let beamFrom: THREE.Vector3 | null = null;
  const moteTexCanvas = document.createElement("canvas");
  moteTexCanvas.width = moteTexCanvas.height = 32;
  {
    const mx = moteTexCanvas.getContext("2d")!;
    const grad = mx.createRadialGradient(16, 16, 1, 16, 16, 15);
    grad.addColorStop(0, "rgba(255,233,179,1)");
    grad.addColorStop(1, "rgba(255,209,102,0)");
    mx.fillStyle = grad;
    mx.fillRect(0, 0, 32, 32);
  }
  const moteTex = new THREE.CanvasTexture(moteTexCanvas);

  const attachWishBeam = (fromLocal: THREE.Vector3) => {
    beamFrom = fromLocal.clone();
    // Faint guide line.
    const vec = BEAM_TARGET.clone().sub(beamFrom);
    const len = vec.length();
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.5, 0.09, len, 8, 1, true),
      new THREE.MeshBasicMaterial({
        color: "#ffd166",
        transparent: true,
        opacity: 0.07,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        fog: false,
      }),
    );
    beam.position.copy(beamFrom).addScaledVector(vec, 0.5);
    beam.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), vec.clone().normalize().negate());
    group.add(beam);
    // The falling motes.
    motes = [];
    for (let i = 0; i < 14; i++) {
      const s = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: moteTex,
          transparent: true,
          opacity: 0,
          depthWrite: false,
          fog: false,
        }),
      );
      s.scale.setScalar(0.5 + (i % 3) * 0.2);
      group.add(s);
      motes.push(s);
    }
  };

  // Load the roadmap snapshot (regenerated by every Mission Control sweep).
  fetch("/roadmap.json")
    .then((r) => r.json())
    .then((j: { generated?: string; items?: RoadmapItem[] }) => {
      items = Array.isArray(j?.items) ? j.items : [];
      generated = j?.generated ?? null;
      draw();
    })
    .catch(() => {
      /* board keeps its placeholder */
    });

  let t = 0;
  return {
    group,
    setWishes(w) {
      wishes = w;
      draw();
    },
    attachWishBeam,
    update(dt, now) {
      t += dt;
      glow.intensity = 4.5 + Math.sin(t * 1.4) * 1.5;
      if (motes && beamFrom) {
        for (let i = 0; i < motes.length; i++) {
          const k = ((now * 0.00006 * (1 + (i % 4) * 0.22) + i / motes.length) % 1 + 1) % 1;
          const s = motes[i];
          s.position.lerpVectors(beamFrom, BEAM_TARGET, k);
          s.position.x += Math.sin(now * 0.001 + i * 2.4) * 0.35;
          s.position.z += Math.cos(now * 0.0013 + i * 1.7) * 0.35;
          (s.material as THREE.SpriteMaterial).opacity =
            k < 0.08 ? k / 0.08 : k > 0.9 ? (1 - k) / 0.1 : 0.85;
        }
      }
    },
  };
}
